    rng=np.random.default_rng(seed); best=None
    for _ in range(n):
        p0=rng.normal(scale=1.0,size=k)
        if rng.random()<0.5: p0[-1]=abs(p0[-1])
        g=lambda p: np.nan_to_num(f(p)-y, nan=1e3, posinf=1e3, neginf=-1e3)
        try:
            r=least_squares(g,p0,max_nfev=500)
            if best is None or r.cost<best.cost: best=r
        except Exception as e:
            pass
    return best
